// Caminho: gestores/servidor/Arcoll.WinUI3/Services/PenteFino/RegistryCheckers.cs
using Microsoft.Win32;
using System.Text.Json;
namespace Arcoll.WinUI3.Services.PenteFino;
public static class RegistryValues
{
    public static string Encode(object? value,RegistryValueKind kind)=>JsonSerializer.Serialize(new{kind=(int)kind,value});
    public static object Decode(string json,RegistryValueKind kind){using var doc=JsonDocument.Parse(json);var value=doc.RootElement.GetProperty("value");return kind switch{RegistryValueKind.Binary=>value.GetBytesFromBase64(),RegistryValueKind.DWord=>value.GetInt32(),RegistryValueKind.QWord=>value.GetInt64(),RegistryValueKind.MultiString=>value.EnumerateArray().Select(x=>x.GetString()??"").ToArray(),_=>value.GetString()??""};}
    public static (RegistryKey Root,string Key,string Name) Open(string reference,bool write){var parts=reference.Split('|',4);if(parts.Length!=4||!Enum.TryParse<RegistryHive>(parts[0],out var hive)||!Enum.TryParse<RegistryView>(parts[1],out var view)||hive is not(RegistryHive.CurrentUser or RegistryHive.LocalMachine))throw new InvalidDataException("Referência de registro inválida.");var root=RegistryKey.OpenBaseKey(hive,view);return(root,parts[2],parts[3]);}
    public static string Ref(RegistryHive hive,RegistryView view,string key,string name)=>$"{hive}|{view}|{key}|{name}";
    public static bool Allowed(string reference,string kind){var parts=reference.Split('|',4);if(parts.Length!=4)return false;var key=parts[2];return kind=="startup"?key.Equals(@"Software\Microsoft\Windows\CurrentVersion\Run",StringComparison.OrdinalIgnoreCase):kind=="registry"&&(key.StartsWith(@"Software\Microsoft\Windows\CurrentVersion\App Paths\",StringComparison.OrdinalIgnoreCase)||key.Equals(@"Software\Microsoft\Windows\CurrentVersion\SharedDLLs",StringComparison.OrdinalIgnoreCase));}
    public static string RegFile(string reference,string before,string kindName){var parts=reference.Split('|',4);if(parts.Length!=4||parts.Any(x=>x.Contains('\n')||x.Contains('\r'))||parts[2].Contains(']'))throw new InvalidDataException("Referência inválida para exportação .reg.");var hive=parts[0]=="CurrentUser"?"HKEY_CURRENT_USER":parts[0]=="LocalMachine"?"HKEY_LOCAL_MACHINE":throw new InvalidDataException("Hive não permitido.");var name=parts[3].Length==0?"@":"\""+parts[3].Replace("\\","\\\\").Replace("\"","\\\"")+"\"";var encoded="-";
        if(before.Length>0){var kind=Enum.Parse<RegistryValueKind>(kindName);var value=Decode(before,kind);if(kind==RegistryValueKind.DWord)encoded="dword:"+unchecked((uint)(int)value).ToString("x8");else{byte[] bytes=kind switch{RegistryValueKind.Binary=>(byte[])value,RegistryValueKind.QWord=>BitConverter.GetBytes((long)value),RegistryValueKind.MultiString=>System.Text.Encoding.Unicode.GetBytes(string.Join("\0",(string[])value)+"\0\0"),RegistryValueKind.String or RegistryValueKind.ExpandString=>System.Text.Encoding.Unicode.GetBytes((string)value+"\0"),_=>throw new InvalidDataException("Tipo não suportado para restauração.")};var prefix=kind switch{RegistryValueKind.Binary=>"hex:",RegistryValueKind.QWord=>"hex(b):",RegistryValueKind.MultiString=>"hex(7):",RegistryValueKind.ExpandString=>"hex(2):",_=>"hex(1):"};encoded=prefix+string.Join(",",bytes.Select(x=>x.ToString("x2")));}}
        return "Windows Registry Editor Version 5.00\r\n\r\n["+hive+"\\"+parts[2]+"]\r\n"+name+"="+encoded+"\r\n";
    }
    public static bool MissingLocalPath(string value){var text=Environment.ExpandEnvironmentVariables(value.Trim().Trim('"'));if(!Path.IsPathRooted(text)||text.StartsWith(@"\\")||text.Contains('"'))return false;var root=Path.GetPathRoot(text);if(root is null||!Directory.Exists(root))return false;try{if(new DriveInfo(root).DriveType!=DriveType.Fixed)return false;var extension=Path.GetExtension(text);return (extension.Equals(".exe",StringComparison.OrdinalIgnoreCase)||extension.Equals(".dll",StringComparison.OrdinalIgnoreCase))&&!File.Exists(text);}catch(IOException){return false;}}
}
public sealed class RegistryChecker(string id,string title):IChecker
{
    public string Id=>id;public string Title=>title;
    public Task<CheckResult> ScanAsync(ScanContext context,CancellationToken ct)=>Task.Run(()=>{
        var rows=new List<Finding>();var notes=new List<string>();var complete=true;
        if(!OperatingSystem.IsWindows())return new CheckResult(Id,Title,[],["Consulta disponível somente no Windows."],false);
        foreach(var hive in new[]{RegistryHive.CurrentUser,RegistryHive.LocalMachine})foreach(var view in new[]{RegistryView.Registry64,RegistryView.Registry32}){
            ct.ThrowIfCancellationRequested();if(Id=="startup"&&hive==RegistryHive.CurrentUser&&view==RegistryView.Registry32)continue;try{using var root=RegistryKey.OpenBaseKey(hive,view);
                if(Id=="startup"){
                    const string path=@"Software\Microsoft\Windows\CurrentVersion\Run";using var run=root.OpenSubKey(path);if(run is null)continue;
                    using var approved=root.OpenSubKey(@"Software\Microsoft\Windows\CurrentVersion\Explorer\StartupApproved\"+(hive==RegistryHive.LocalMachine&&view==RegistryView.Registry32?"Run32":"Run"));
                    foreach(var name in run.GetValueNames().Take(500)){ct.ThrowIfCancellationRequested();var value=run.GetValue(name,null,RegistryValueOptions.DoNotExpandEnvironmentNames);var kind=run.GetValueKind(name);var command=Environment.ExpandEnvironmentVariables(value as string??"");var windows=Environment.GetFolderPath(Environment.SpecialFolder.Windows);if(windows.Length>0&&command.Contains(windows+"\\",StringComparison.OrdinalIgnoreCase))continue;var reference=RegistryValues.Ref(hive,view,path,name);var disabled=approved?.GetValue(name)is byte[] data&&data.Length>=1&&(data[0]==3||data[0]==7);if(disabled)continue;rows.Add(new(ResultsStore.Hash("startup|"+reference),Id,name,reference,0,"Programa habilitado no logon. O impacto de boot não foi aferido individualmente.","Desabilitar via StartupApproved; comando original preservado",true,"startup",Expected:RegistryValues.Encode(value,kind),ValueKind:kind.ToString(),Severity:"review"));}
                }else{
                    const string appPaths=@"Software\Microsoft\Windows\CurrentVersion\App Paths";using var apps=root.OpenSubKey(appPaths);
                    if(apps is not null)foreach(var child in apps.GetSubKeyNames().Take(context.Options.Mode=="quick"?800:4000)){ct.ThrowIfCancellationRequested();using var key=apps.OpenSubKey(child);var value=key?.GetValue("",null,RegistryValueOptions.DoNotExpandEnvironmentNames);if(value is not string path||!RegistryValues.MissingLocalPath(path))continue;var reference=RegistryValues.Ref(hive,view,appPaths+"\\"+child,"");var kind=key!.GetValueKind("");rows.Add(new(ResultsStore.Hash(reference),Id,child,reference,0,"Referência App Paths aponta para executável local não encontrado: "+path,"Remover somente o valor órfão; backup e restauração obrigatórios",true,"registry",Expected:RegistryValues.Encode(value,kind),ValueKind:kind.ToString(),Severity:"review"));}
                    const string sharedPath=@"Software\Microsoft\Windows\CurrentVersion\SharedDLLs";using var shared=root.OpenSubKey(sharedPath);if(shared is not null)foreach(var name in shared.GetValueNames().Take(4000)){ct.ThrowIfCancellationRequested();if(!RegistryValues.MissingLocalPath(name))continue;var kind=shared.GetValueKind(name);var reference=RegistryValues.Ref(hive,view,sharedPath,name);rows.Add(new(ResultsStore.Hash(reference),Id,Path.GetFileName(name),reference,0,"Contador SharedDLLs de biblioteca local não encontrada.","Remover somente o valor órfão com backup",true,"registry",Expected:RegistryValues.Encode(shared.GetValue(name),kind),ValueKind:kind.ToString(),Severity:"review"));}
                    if(context.Options.Mode=="detailed")AdditionalDiagnostics.Registry(root,hive,view,rows,ct);
                }
            }catch(Exception e)when(e is UnauthorizedAccessException or System.Security.SecurityException or IOException){complete=false;notes.Add(hive+"/"+view+": "+e.Message);}
        }
        if(Id=="startup"){
            foreach(var folder in new[]{Environment.GetFolderPath(Environment.SpecialFolder.Startup),Environment.GetFolderPath(Environment.SpecialFolder.CommonStartup)})if(Directory.Exists(folder))foreach(var file in Directory.EnumerateFiles(folder).Take(300)){ct.ThrowIfCancellationRequested();rows.Add(new(ResultsStore.Hash(file),Id,Path.GetFileName(file),file,0,"Atalho na pasta Inicializar.","Revisar na ferramenta Inicialização",false,"info",Severity:"review"));}
            try{AdditionalDiagnostics.Startup(rows,notes,ct);}catch(Exception e)when(e is UnauthorizedAccessException or IOException){complete=false;notes.Add("Inventário complementar parcial: "+e.Message);}
        }else notes.Add("Correção limitada a valores App Paths/SharedDLLs comprovadamente ausentes. CLSID/COM, Uninstall e MUI Cache são diagnosticados no modo Detalhado, sem alteração automática; desfragmentação não é executada.");
        return new CheckResult(Id,Title,rows.DistinctBy(x=>x.Id).ToList(),notes,complete);
    },ct);
}
public sealed class UpdatesChecker:IChecker
{
    public string Id=>"updates";public string Title=>"Atualizações";
    public Task<CheckResult> ScanAsync(ScanContext context,CancellationToken ct)=>Task.Run(()=>{
        var items=new List<Finding>();var notes=new List<string>();var bankPath=context.Store.LocalPath("versions.json");var bank=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);
        if(File.Exists(bankPath)){if(new FileInfo(bankPath).Length>262144)throw new InvalidDataException("Banco de versões excede 256 KB.");bank=JsonSerializer.Deserialize<Dictionary<string,string>>(File.ReadAllText(bankPath))??bank;}
        if(!OperatingSystem.IsWindows())return new CheckResult(Id,Title,[],["Inventário de aplicativos disponível no Windows."],false);
        foreach(var hive in new[]{RegistryHive.CurrentUser,RegistryHive.LocalMachine})foreach(var view in new[]{RegistryView.Registry64,RegistryView.Registry32}){ct.ThrowIfCancellationRequested();using var root=RegistryKey.OpenBaseKey(hive,view);using var uninstall=root.OpenSubKey(@"Software\Microsoft\Windows\CurrentVersion\Uninstall");if(uninstall is null)continue;foreach(var child in uninstall.GetSubKeyNames().Take(2500)){ct.ThrowIfCancellationRequested();using var key=uninstall.OpenSubKey(child);var name=key?.GetValue("DisplayName")as string;if(string.IsNullOrWhiteSpace(name))continue;var installed=key!.GetValue("DisplayVersion")as string??"Não informada";var available=bank.TryGetValue(name,out var latest)?latest:"Não consultada";var outdated=Version.TryParse(installed,out var current)&&Version.TryParse(available,out var next)&&next>current;items.Add(new(ResultsStore.Hash(name+"|"+installed),Id,name,"Registro de programas instalados",0,"Instalada: "+installed+" · Banco local: "+available,outdated?"Atualização disponível; revisar na ferramenta Atualizações":"Somente inventário; sem atualização confirmada",false,"info",Severity:outdated?"review":"info"));}}
        notes.Add(bank.Count==0?"Banco local de versões não configurado. Inventário não equivale a aplicativos atualizados.":"Comparação apenas para nomes/versões reconhecidos no banco local; versões fora do padrão não são classificadas.");notes.Add("Nenhum instalador ou WinGet é executado na análise. Atualizações ficam na ferramenta existente porque o rollback não é garantido por todos os fornecedores.");return new CheckResult(Id,Title,items.DistinctBy(x=>x.Id).ToList(),notes,bank.Count>0);
    },ct);
}
